//! Explicit compatibility adapter for historical exact-eight necessary-form routing.
//!
//! Canonical D4 identity lives in `necessary_forms.rs`. This module is the only
//! evaluator-side place where the old generated byte table is interpreted as a
//! transition mechanism. It returns only a mechanism class; callers must not
//! treat the byte as canonical language identity.

use crate::{semantic_registry, Sens8};

use super::necessary_forms::NecessaryFormIdentity;

mod generated {
    include!("necessary_forms_generated.rs");
}

/// Resolve one historical exact-eight registry coordinate to its mechanism.
///
/// This is a compatibility projection only. It does not construct a canonical
/// Core identity and must shrink as callers move to domain-qualified routing.
pub(crate) fn identity_for_semantic_id(
    semantic_id: Sens8,
) -> Option<NecessaryFormIdentity> {
    generated::NECESSARY_FORM_DISPATCH
        .iter()
        .find(|row| row.semantic_id == semantic_id.packed_byte())
        .map(|row| match row.mechanism {
            generated::NecessaryFormMechanism::Define => NecessaryFormIdentity::Define,
            generated::NecessaryFormMechanism::Lambda => NecessaryFormIdentity::Lambda,
        })
}

/// Compatibility-only surface route.
///
/// Human spelling is resolved by the registry first. The resulting legacy byte
/// is used only to recover the already-known mechanism class.
pub(crate) fn identity_for_symbol(name: &str) -> Option<NecessaryFormIdentity> {
    semantic_registry::admitted_semantic_id_for_surface(name)
        .and_then(identity_for_semantic_id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn legacy_adapter_recovers_only_known_necessary_form_mechanisms() {
        let lambda = semantic_registry::admitted_semantic_id_for_surface("lambda")
            .expect("lambda compatibility coordinate");
        let define = semantic_registry::admitted_semantic_id_for_surface("define")
            .expect("define compatibility coordinate");
        let def = semantic_registry::admitted_semantic_id_for_surface("def")
            .expect("def compatibility coordinate");

        assert_eq!(
            identity_for_semantic_id(lambda),
            Some(NecessaryFormIdentity::Lambda)
        );
        assert_eq!(
            identity_for_semantic_id(define),
            Some(NecessaryFormIdentity::Define)
        );
        assert_eq!(
            identity_for_semantic_id(def),
            Some(NecessaryFormIdentity::Define)
        );
        assert_eq!(
            identity_for_semantic_id(crate::sens!(00001100)),
            None
        );
    }
}
